import json,os,subprocess
from pathlib import Path
r={"mode":"READ_ONLY","purpose":"retired REA account owned files and hidden global installs"}
for group in (["/etc","/var","/tmp","/root","/home","/opt","/usr/local","/srv"],):
 try:
  p=subprocess.run(["/usr/bin/find",*group,"-xdev","-uid","994","-print"],capture_output=True,text=True,timeout=85)
  vals=[x for x in p.stdout.splitlines() if x.strip()]
  r["uid994_files"]={"find_exit":p.returncode,"count":len(vals),"first_60_paths":vals[:60],"truncated":len(vals)>=60}
 except subprocess.TimeoutExpired:r["uid994_files"]={"timeout":True}
excepts=[]
w=("rea-mcp","rea-agents","rea-reversa","rea-final","rea-trial","rea-original","rea-chatgpt")
for base in ("/root","/home/ubuntu","/opt","/usr/local","/var/lib","/etc","/tmp","/var/tmp","/srv"):
 root=Path(base)
 if not root.is_dir():continue
 for d,dirs,files in os.walk(root,followlinks=False):
  dp=Path(d)
  depth=len(dp.parts)-len(root.parts)
  if depth>=5:dirs[:]=[]
  dirs[:]=[x for x in dirs if x not in ("node_modules",".git",".venv","venv","archive","backups","releases") and not (base=="/srv" and x=="projects")]
  for x in dirs+files:
   if any(n in x.lower() for n in w):
    f=dp/x
    try:
     typ="link" if f.is_symlink() else "dir" if f.is_dir() else "file"
    except OSError:typ="unknown"
    excepts.append({"path":str(f),"type":typ})
r["named_rea_like"]={"total":len(excepts),"first_85":excepts[:85]}
