for p in ("/usr/bin/rea","/usr/bin/rea-mcp","/usr/local/bin/rea","/usr/local/bin/rea-mcp","/usr/local/lib/node_modules/rea-agents","/usr/lib/node_modules/rea-agents","/opt/rea","/opt/rea-reversa"):
